#include <stdio.h>
int main(void) {
    double cores = 1024, flop_per_cycle = 2, ghz = 1.5;  /* FMA = 2 FLOP/周期 */
    double flops = cores * flop_per_cycle * ghz * 1e9;
    printf("GPU 核心数 = 1024\n");
    printf("每核心每周期浮点操作 = 2 (FMA)\n");
    printf("主频 = 1.5 GHz\n");
    printf("峰值 FLOPS = 1024 * 2 * 1.5e9 = %.3e FLOPS\n", flops);
    printf("           = %.3f TFLOPS\n", flops / 1e12);
    return 0;
}
